#################################################################

:hasInvoiceNumber a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number assigned to the invoice message." .

:hasNetPrice a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal ;
    rdfs:label "has net price" ;
    rdfs:comment "The net price of an item or invoice line." .

:hasQuantity a owl:DatatypeProperty ;
    rdfs:domain :InvoiceLine ;
    rdfs:range xsd:decimal ;
    rdfs:label "has quantity" ;
    rdfs:comment "The quantity of items on an invoice line." .

:hasTaxAmount a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :Tax ;
    rdfs:range xsd:decimal ;
    rdfs:label "has tax amount" ;
    rdfs:comment "The tax amount applied to a section or invoice." .

:hasInvoiceAmount a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :SummarySection ;
    rdfs:range xsd:decimal ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "The total invoice amount in the summary section." .

:hasDate a owl:DatatypeProperty ;
    rdfs:domain :HeaderSection ;
    rdfs:range xsd:dateTime ;
    rdfs:label "has date" ;
    rdfs:comment "A date value in the header section (OWL 2 DL compliant xsd:dateTime)." .

:hasReferenceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range xsd:string ;
    rdfs:label "has reference value" ;
    rdfs:comment "The value of the reference number." .

:hasAddressLine a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "has address line" ;
    rdfs:comment "A line of the postal address." .

:hasPostalCode a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "has postal code" ;
    rdfs:comment "Postal code for the address." .

:hasCity a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "has city" ;
    rdfs:comment "City for the address." .

:hasCountryCode a owl:DatatypeProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "has country code" ;
    rdfs:comment "Country code for the address." .

# Organization attribute extensions for CQ5
:hasLegalName a owl:DatatypeProperty ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    rdfs:label "has legal name" ;
    rdfs:comment "The full legal name of the organization." .

:hasPhoneNumber a owl:DatatypeProperty ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    rdfs:label "has phone number" ;
    rdfs:comment "Contact phone number for the organization." .

:hasEmail a owl:DatatypeProperty ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    rdfs:label "has email" ;
    rdfs:comment "Contact email address for the organization." .

:hasVATNumber a owl:DatatypeProperty ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    rdfs:label "has VAT number" ;
    rdfs:comment "VAT identifier for the organization." .

:hasRegistrationNumber a owl:DatatypeProperty ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    rdfs:label "has registration number" ;
    rdfs:comment "Company registration number." .

# Item attribute extensions for CQ8
:hasProductCode a owl:DatatypeProperty ;
    rdfs:domain :Item ;
    rdfs:range xsd:string ;
    rdfs:label "has product code" ;
    rdfs:comment "A product code (e.g., GTIN, SKU) for the item." .

:hasDescription a owl:DatatypeProperty ;
    rdfs:domain :Item ;
    rdfs:range xsd:string ;
    rdfs:label "has description" ;
    rdfs:comment "A textual description of the item." .

:hasUnitOfMeasure a owl:DatatypeProperty ;
    rdfs:domain :Item ;
    rdfs:range xsd:string ;
    rdfs:label "has unit of measure" ;
    rdfs:comment "Unit of measure for the item (e.g., 'kg', 'pcs')." .

#################################################################
# Section: Disjointness and Unions (expanded)
#################################################################

:Organization owl:disjointWith :AgentRole , :Address .
:Segment owl:disjointWith :Organization , :SectionUnion .
:DetailSection owl:disjointWith :HeaderSection , :SummarySection .
:SummarySection owl:disjointWith :HeaderSection .
:InvoiceLine owl:disjointWith :Item .
:Price owl:disjointWith :Tax .
:AgentRole owl:disjointWith :Address .
:SectionUnion owl:disjointUnionOf ( :HeaderSection :DetailSection :SummarySection ) .

#################################################################
# Section: Restrictions & Axioms (expanded for CQ13)
#################################################################

:InvoiceMessage rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :hasSection ;
    owl:allValuesFrom :SectionUnion
] .

:OrganizationRoleAssignment rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :assignedOrganization ;
    owl:someValuesFrom :Organization
] , [
    a owl:Restriction ;
    owl:onProperty :assignedRole ;
    owl:someValuesFrom :AgentRole
] .

:InvoiceLine rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :describesItem ;
    owl:someValuesFrom :Item
] , [
    a owl:Restriction ;
    owl:onProperty :hasPrice ;
    owl:someValuesFrom :Price
] .

:Organization rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :hasAddress ;
    owl:allValuesFrom :Address
] , [
    a owl:Restriction ;
    owl:onProperty :hasGlobalLocationNumber ;
    owl:allValuesFrom :GlobalLocationNumber
] .

# Example: GCA for Buyer role
:Buyer a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            :OrganizationRoleAssignment
            [ a owl:Restriction ;
              owl:onProperty :assignedRole ;
              owl:hasValue :BuyerRole ]
        )
    ] ;
    rdfs:label "Buyer" ;
    rdfs:comment "A role assignment where the assigned role is Buyer." .

:BuyerRole a :AgentRole ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "AgentRole individual representing Buyer." .

#################################################################
# Section: Annotations for Alignment and Compliance
#################################################################

:InvoiceMessage rdfs:seeAlso :EN16931Compliance , :P2POAlignment .

#################################################################
# Section: ValidationConstraint Individuals (for CQ13)
#################################################################

:MandatoryInvoiceNumber a :ValidationConstraint ;
    rdfs:label "Mandatory Invoice Number" ;
    rdfs:comment "Validation constraint: InvoiceMessage must have exactly one invoice number." .

:MandatoryGLN a :ValidationConstraint ;
    rdfs:label "Mandatory GLN" ;
    rdfs:comment "Validation constraint: Organization must have a Global Location Number (GLN) as required by D96A." .

#################################################################
# Section: Individuals (Example)
#################################################################

:plusDelimiter a :EDIFACTDelimiter ;
    rdfs:label "Plus Delimiter" ;
    rdfs:comment "The plus sign ('+') used as a segment delimiter in EDIFACT." .

:colonDelimiter a :EDIFACTDelimiter ;
    rdfs:label "Colon Delimiter" ;
    rdfs:comment "The colon (':') used as a composite element delimiter in EDIFACT." .

:apostropheDelimiter a :EDIFACTDelimiter ;
    rdfs:label "Apostrophe Delimiter" ;
    rdfs:comment "The apostrophe (''') used as a message delimiter in EDIFACT." .

